import { type InferredInput, defineScript, gezel } from '@bendyline/gezel-sdk';
import { logStore, rosterStore } from '@bendyline/gezel-sdk/stores';

export const meta = defineScript({
  name: 'voice-store',
  description:
    "Read and update Customer Voice: the feedback log (feedback.json), its themes (themes.json) and the action list (actions.json). action:'status' for each theme's count and trend, what is not sorted yet, the replies owed and the open actions; 'log' to save a review or survey answer (the same words from the same author are never duplicated); 'tag' to sort feedback into themes; 'reply' to save a reply; 'mark_replied' once a reply is posted; 'add_action' (an existing title is updated); 'set_action' to move an action; 'import' to read a CSV of reviews under imports/; 'list' for every entry.",
  inputs: {
    action: {
      type: 'string',
      description: "One of 'status', 'log', 'tag', 'reply', 'mark_replied', 'add_action', 'set_action', 'import', or 'list'.",
      required: true,
    },
    id: {
      type: 'string',
      description: "Feedback id, e.g. 'fb-12' (for tag, several comma-separated: 'fb-12, fb-13'); for set_action an action id like 'ac-2'.",
    },
    text: { type: 'string', description: "The customer's words, exactly as written." },
    source: { type: 'string', description: 'google, yelp, tripadvisor, survey, email, social, in-person, or other.' },
    rating: { type: 'number', description: 'Stars, 1 to 5.' },
    stars: { type: 'string', description: "Stars as text from the page, '1' to '5'." },
    author: { type: 'string', description: 'Who wrote it, as it appears.' },
    receivedAt: { type: 'string', description: 'The day it was written, YYYY-MM-DD (default today).' },
    themes: { type: 'string', description: "Theme names, comma-separated, e.g. 'Slow weekend service, Friendly staff'." },
    kind: { type: 'string', description: 'For a new theme: praise, problem, or request.' },
    replyNeeded: { type: 'boolean', description: 'Whether it needs a reply (default: public reviews of 3 stars or fewer).' },
    reply: { type: 'string', description: 'The reply text, ready to post.' },
    posted: { type: 'boolean', description: 'True once the reply is live.' },
    title: { type: 'string', description: "For actions: the action's title. Also finds it when no id is given." },
    theme: { type: 'string', description: 'For actions: the theme it answers, by name or id. For list: only that theme.' },
    owner: { type: 'string', description: 'Who takes the action.' },
    dueAt: { type: 'string', description: 'When the action is due, YYYY-MM-DD.' },
    status: { type: 'string', description: 'For set_action: todo, doing, or done.' },
    note: { type: 'string', description: 'What happened.' },
    file: { type: 'string', description: "For import: the CSV's workspace path, e.g. 'imports/google-reviews.csv'." },
  },
  outputs: {
    themes: { type: 'number', description: 'Themes being tracked.' },
    repliesNeeded: { type: 'number', description: 'Feedback that still needs a reply posted.' },
    unsorted: { type: 'number', description: 'Feedback not sorted into a theme.' },
    openActions: { type: 'number', description: 'Actions not done.' },
    summary: { type: 'string', description: 'The picture, or the listing.' },
  },
  requires: ['workspace.read', 'workspace.write'],
} as const);

const input = gezel.input as InferredInput<typeof meta>;

// ── voice-rules-start ──
// Pure derivations: the feedback log folded into entries (with their themes,
// replies and edits), theme counts over the last 30 days against the 30
// before, the replies still owed, the CSV reader for imports, and the picture
// the crew reads. Kept self-contained between these sentinels so unit tests
// execute the shipped bytes.
var DAY_MS = 86400000;
var SOURCES = ['google', 'yelp', 'tripadvisor', 'survey', 'email', 'social', 'in-person', 'other'];
var PUBLIC_SOURCES = ['google', 'yelp', 'tripadvisor', 'social'];
var THEME_KINDS = ['praise', 'problem', 'request'];
var FEEDBACK_KINDS = ['review', 'survey', 'comment'];
var ACTION_STAGES = ['todo', 'doing', 'done'];

function pad(n) {
  return n < 10 ? '0' + n : String(n);
}
function localDay(ms) {
  var d = new Date(ms);
  return d.getFullYear() + '-' + pad(d.getMonth() + 1) + '-' + pad(d.getDate());
}
function normalizeDate(text) {
  var raw = String(text || '').trim();
  if (/^\d{4}-\d{2}-\d{2}$/.test(raw)) return raw;
  if (/^\d{4}-\d{2}-\d{2}[T ]/.test(raw)) return raw.slice(0, 10);
  var parsed = Date.parse(raw);
  return raw && isFinite(parsed) ? localDay(parsed) : null;
}
function daysAgo(day, nowMs) {
  var then = Date.parse(String(day || '').slice(0, 10) + 'T00:00:00');
  var today = Date.parse(localDay(nowMs) + 'T00:00:00');
  return isFinite(then) ? Math.round((today - then) / DAY_MS) : 0;
}
function nameKey(text) {
  return String(text || '').trim().toLowerCase().replace(/\s+/g, ' ');
}
function textKey(text, author) {
  return nameKey(author) + '|' + nameKey(text).slice(0, 160);
}
function sourceOf(text) {
  var s = nameKey(text);
  if (SOURCES.indexOf(s) >= 0) return s;
  if (/google/.test(s)) return 'google';
  if (/yelp/.test(s)) return 'yelp';
  if (/trip ?advisor/.test(s)) return 'tripadvisor';
  if (/survey|questionnaire|form|typeform|nps|poll/.test(s)) return 'survey';
  if (/e-?mail|inbox/.test(s)) return 'email';
  if (/facebook|instagram|twitter|bluesky|tiktok|social|linkedin|\bx\b/.test(s)) return 'social';
  if (/in person|in-person|counter|store|shop floor|phone|call/.test(s)) return 'in-person';
  return 'other';
}
function feedbackKind(source) {
  return source === 'survey' ? 'survey' : PUBLIC_SOURCES.indexOf(source) >= 0 ? 'review' : 'comment';
}
// Stars from a number, '4/5', '4 stars' or a row of star characters; null when absent.
function ratingOf(value, scale) {
  if (value === undefined || value === null || value === '') return null;
  var n = typeof value === 'number' ? value : NaN;
  if (typeof value === 'string') {
    var starCount = (value.match(/★/g) || []).length;
    n = starCount ? starCount : parseFloat(value.replace(',', '.'));
  }
  if (!isFinite(n)) return null;
  if (scale === 10) n = n / 2;
  return Math.min(5, Math.max(1, Math.round(n)));
}
function needsReply(source, rating, explicit) {
  if (explicit === true || explicit === false) return explicit;
  return PUBLIC_SOURCES.indexOf(source) >= 0 && typeof rating === 'number' && rating <= 3;
}
function guessKind(items) {
  var rated = items.filter(function (e) { return typeof e.rating === 'number'; });
  var avg = rated.length ? rated.reduce(function (s, e) { return s + e.rating; }, 0) / rated.length : null;
  var asks = items.some(function (e) { return /\b(wish|please|would love|could you|should|add|bring back|more)\b/i.test(e.text || ''); });
  if (avg !== null && avg >= 4 && !asks) return 'praise';
  if (asks && (avg === null || avg >= 3)) return 'request';
  return avg !== null && avg >= 4 ? 'praise' : 'problem';
}
// The log, folded: each feedback event becomes an entry; later events tag it, edit it, reply to it.
function entries(events) {
  var list = [], byId = {};
  (events || []).forEach(function (e) {
    var d = e.data || {};
    if (FEEDBACK_KINDS.indexOf(e.kind) >= 0 && d.id && !byId[d.id]) {
      var entry = {
        id: d.id, kind: e.kind, text: e.note || '', source: d.source || 'other',
        rating: typeof d.rating === 'number' ? d.rating : null, author: d.author || '',
        day: d.day || String(e.at || '').slice(0, 10), themes: Array.isArray(d.themes) ? d.themes.slice() : [],
        replyNeeded: !!d.replyNeeded, reply: '', posted: false,
      };
      list.push(entry);
      byId[d.id] = entry;
      return;
    }
    var target = byId[d.feedbackId];
    if (!target) return;
    if (e.kind === 'tagged') target.themes = Array.isArray(d.themes) ? d.themes.slice() : [];
    else if (e.kind === 'edited') {
      if (typeof d.rating === 'number') target.rating = d.rating;
      if (d.source) target.source = d.source;
      if (typeof d.replyNeeded === 'boolean') target.replyNeeded = d.replyNeeded;
      if (Array.isArray(d.themes)) target.themes = d.themes.slice();
    } else if (e.kind === 'reply') {
      if (e.note) target.reply = e.note;
      if (d.posted) target.posted = true;
    } else if (e.kind === 'replied') target.posted = true;
  });
  return list;
}
function nextFeedbackNumber(events) {
  var max = 0;
  (events || []).forEach(function (e) {
    var m = /^fb-(\d+)$/.exec(String((e.data && e.data.id) || ''));
    if (m) max = Math.max(max, Number(m[1]));
  });
  return max + 1;
}
function themeStats(themes, list, nowMs) {
  return themes
    .filter(function (t) { return t.status !== 'retired'; })
    .map(function (t) {
      var hits = list.filter(function (e) { return e.themes.indexOf(t.id) >= 0; });
      var recent = hits.filter(function (e) { var d = daysAgo(e.day, nowMs); return d >= 0 && d < 30; }).length;
      var before = hits.filter(function (e) { var d = daysAgo(e.day, nowMs); return d >= 30 && d < 60; }).length;
      var trend = !recent && !before ? 'quiet' : !before ? 'new this month' : recent > before ? 'rising' : recent < before ? 'falling' : 'steady';
      var latest = hits.slice().sort(function (a, b) { return String(b.day).localeCompare(String(a.day)); })[0] || null;
      return { id: t.id, name: String(t.fields.name), kind: t.fields.kind || 'problem', total: hits.length, recent: recent, before: before, trend: trend, latest: latest };
    })
    .sort(function (a, b) { return b.recent - a.recent || b.total - a.total || a.name.localeCompare(b.name); });
}
function repliesOwed(list) {
  return list
    .filter(function (e) { return e.replyNeeded && !e.posted; })
    .sort(function (a, b) { return String(a.day).localeCompare(String(b.day)) || a.id.localeCompare(b.id, undefined, { numeric: true }); });
}
function quote(text, length) {
  var t = String(text || '').replace(/\s+/g, ' ').trim();
  return t.length > length ? t.slice(0, length - 1).trim() + '…' : t;
}
function feedbackLine(e, names) {
  var themeNames = e.themes.map(function (id) { return names[id] || id; });
  return (
    e.id + ' ' + e.source + (e.rating ? ' ' + e.rating + '/5' : '') + (e.author ? ' by ' + e.author : '') + ', ' + e.day + ': "' + quote(e.text, 110) + '"' +
    (themeNames.length ? ' [' + themeNames.join(', ') + ']' : ' [not sorted]') +
    (e.replyNeeded && !e.posted ? (e.reply ? ', reply drafted, not posted yet' : ', needs a reply') : e.posted ? ', replied' : '')
  );
}
function capped(items, max, render) {
  var shown = items.slice(0, max).map(render).join(' | ');
  return items.length > max ? shown + ' | and ' + (items.length - max) + ' more' : shown;
}
function picture(themes, list, actions, nowMs) {
  var names = {};
  themes.forEach(function (t) { names[t.id] = String(t.fields.name); });
  var stats = themeStats(themes, list, nowMs);
  var month = list.filter(function (e) { var d = daysAgo(e.day, nowMs); return d >= 0 && d < 30; });
  var rated = month.filter(function (e) { return typeof e.rating === 'number'; });
  var avg = rated.length ? Math.round((rated.reduce(function (s, e) { return s + e.rating; }, 0) / rated.length) * 10) / 10 : null;
  var unsorted = list.filter(function (e) { return !e.themes.length; });
  var owed = repliesOwed(list);
  var open = actions.filter(function (a) { return a.status !== 'done'; });
  var parts = [
    list.length + (list.length === 1 ? ' piece of feedback' : ' pieces of feedback') + ' logged, ' + month.length + ' in the last 30 days' +
      (avg !== null ? ', averaging ' + avg + ' of 5 stars' : '') + '.',
  ];
  parts.push(
    stats.length
      ? 'Themes, most mentioned in the last 30 days first: ' +
          stats.map(function (s) {
            return s.name + ' (' + s.id + ', ' + s.kind + '): ' + s.recent + ' in the last 30 days, ' + s.before + ' in the 30 before, ' + s.trend +
              (s.latest ? '; latest: "' + quote(s.latest.text, 80) + '"' : '');
          }).join(' | ') + '.'
      : 'No themes yet.',
  );
  parts.push(unsorted.length ? 'Not sorted into a theme yet: ' + capped(unsorted, 12, function (e) { return feedbackLine(e, names); }) + '.' : 'Everything is sorted into themes.');
  parts.push(owed.length ? 'Needs a reply, oldest first: ' + capped(owed, 10, function (e) { return feedbackLine(e, names); }) + '.' : 'No replies owed.');
  parts.push(
    open.length
      ? 'Open actions: ' +
          open.map(function (a) {
            var f = a.fields || {};
            return f.title + ' (' + a.id + ', ' + a.status + (f.theme && names[f.theme] ? ', for ' + names[f.theme] : '') + (f.owner ? ', owner ' + f.owner : '') + (f.dueAt ? ', due ' + f.dueAt : '') + ')';
          }).join(' | ') + '.'
      : 'No open actions.',
  );
  return { themes: stats.length, repliesNeeded: owed.length, unsorted: unsorted.length, openActions: open.length, summary: parts.join(' ') };
}
// ── CSV import: a header row names the columns; anything unrecognized is ignored. ──
function parseCsv(text) {
  var src = String(text || '').replace(/^﻿/, '');
  var first = src.split(/\r?\n/, 1)[0] || '';
  var delim = [',', ';', '\t'].map(function (d) { return [d, first.split(d).length]; }).sort(function (a, b) { return b[1] - a[1]; })[0][0];
  var rows = [], row = [], cell = '', quoted = false;
  for (var i = 0; i < src.length; i++) {
    var c = src[i];
    if (quoted) {
      if (c === '"') {
        if (src[i + 1] === '"') { cell += '"'; i++; } else quoted = false;
      } else cell += c;
    } else if (c === '"' && cell === '') quoted = true;
    else if (c === delim) { row.push(cell); cell = ''; }
    else if (c === '\n' || c === '\r') {
      if (c === '\r' && src[i + 1] === '\n') i++;
      row.push(cell); rows.push(row); row = []; cell = '';
    } else cell += c;
  }
  if (cell !== '' || row.length) { row.push(cell); rows.push(row); }
  return rows.filter(function (r) { return r.some(function (v) { return String(v).trim() !== ''; }); });
}
function columnOf(header) {
  var h = nameKey(header);
  if (/(date|created|submitted|posted|timestamp|time|when)/.test(h)) return 'day';
  if (/(rating|stars?|score|nps)/.test(h)) return 'rating';
  if (/(author|reviewer|name|respondent)/.test(h)) return 'author';
  if (/(source|platform|site|channel)/.test(h)) return 'source';
  if (/(review|text|comment|feedback|body|message|answer|response|content|said|why)/.test(h)) return 'text';
  if (/(customer|user|who)/.test(h)) return 'author';
  return null;
}
function csvFeedback(text, defaultSource) {
  var rows = parseCsv(text);
  if (!rows.length) return { items: [], blank: 0, columns: {} };
  var at = {};
  rows[0].forEach(function (h, i) { var col = columnOf(h); if (col && at[col] === undefined) at[col] = i; });
  var hasHeader = Object.keys(at).length > 0;
  var body = hasHeader ? rows.slice(1) : rows;
  if (at.text === undefined) {
    // No column says it holds the words: take the one with the longest cells.
    var widths = (rows[0] || []).map(function (_, i) {
      if (Object.keys(at).some(function (k) { return at[k] === i; })) return -1;
      return body.reduce(function (s, r) { return s + String(r[i] || '').length; }, 0);
    });
    var widest = widths.indexOf(Math.max.apply(null, widths.concat([-1])));
    if (widest >= 0) at.text = widest;
  }
  var scale = at.rating !== undefined && body.some(function (r) { var v = parseFloat(r[at.rating]); return isFinite(v) && v > 5; }) ? 10 : 5;
  var items = [], blank = 0;
  body.forEach(function (r) {
    var words = at.text === undefined ? '' : String(r[at.text] || '').trim();
    if (!words) { blank += 1; return; }
    items.push({
      text: words,
      rating: at.rating === undefined ? null : ratingOf(String(r[at.rating] || '').trim(), scale),
      day: at.day === undefined ? null : normalizeDate(r[at.day]),
      author: at.author === undefined ? '' : String(r[at.author] || '').trim(),
      source: at.source !== undefined && String(r[at.source] || '').trim() ? sourceOf(r[at.source]) : defaultSource,
    });
  });
  return { items: items, blank: blank, columns: at };
}
// ── voice-rules-end ──

const FEEDBACK = 'feedback.json';
const feedback = logStore(gezel.fs, FEEDBACK);
const themes = rosterStore(gezel.fs, 'themes.json', { stages: ['active', 'retired'], idPrefix: 'th' });
const actions = rosterStore(gezel.fs, 'actions.json', { stages: ['todo', 'doing', 'done'], idPrefix: 'ac' });

function upperFirst(text: string): string {
  return text.charAt(0).toUpperCase() + text.slice(1);
}

// Theme names to ids, reusing a theme whose name matches (or one the name clearly means);
// a new name starts a new theme.
async function ensureThemes(text: string, kind: string): Promise<{ ids: string[]; created: string[] }> {
  const all = await themes.list();
  const ids: string[] = [];
  const created: string[] = [];
  for (const raw of String(text).split(/[,;\n]+/)) {
    const name = raw.trim().replace(/^["']|["']$/g, '');
    if (!name) continue;
    let theme = all.find((t) => t.id === name.toLowerCase() || nameKey(t.fields.name) === nameKey(name));
    if (!theme) {
      const near = all.filter((t) => t.status !== 'retired' && (nameKey(t.fields.name).includes(nameKey(name)) || nameKey(name).includes(nameKey(t.fields.name))));
      if (near.length === 1) theme = near[0];
    }
    if (!theme) {
      theme = await themes.add({ status: 'active', fields: { name: upperFirst(name), kind } });
      all.push(theme);
      created.push(String(theme.fields.name));
    }
    if (!ids.includes(theme.id)) ids.push(theme.id);
  }
  return { ids, created };
}

async function themeNames(ids: string[]): Promise<string> {
  const all = await themes.list();
  return ids.map((id) => String(all.find((t) => t.id === id)?.fields.name ?? id)).join(', ');
}

function feedbackIds(list: ReturnType<typeof entries>): string[] {
  const ids = String(input.id ?? '').split(/[\s,;]+/).map((s) => s.trim().toLowerCase()).filter(Boolean);
  if (!ids.length) throw new Error("Pass 'id', e.g. 'fb-12'. Call action:'status' to see the ids.");
  const unknown = ids.filter((id) => !list.some((e) => e.id === id));
  if (unknown.length) {
    throw new Error('No feedback ' + unknown.join(', ') + '. Known ids run from ' + (list[0]?.id ?? 'none') + ' to ' + (list[list.length - 1]?.id ?? 'none') + '.');
  }
  return ids;
}

async function resolveAction(): Promise<string> {
  const all = await actions.list();
  const byId = input.id ? all.find((a) => a.id === input.id!.trim().toLowerCase()) : undefined;
  if (byId) return byId.id;
  const text = input.title ?? input.id;
  if (text) {
    const wanted = nameKey(text);
    const exact = all.filter((a) => nameKey(a.fields.title) === wanted);
    if (exact.length === 1) return exact[0]!.id;
    const partial = all.filter((a) => nameKey(a.fields.title).includes(wanted));
    if (partial.length === 1) return partial[0]!.id;
    if (partial.length > 1) throw new Error("More than one action matches '" + text + "': " + partial.map((a) => a.id + ' ' + String(a.fields.title)).join(', ') + '. Pass id.');
  }
  throw new Error("Pass 'id' (e.g. 'ac-2') or the action's 'title'. Actions: " + (all.map((a) => a.id + ' ' + String(a.fields.title)).join(', ') || 'none yet') + '.');
}

// Many rows at once: one read and one write of the log, in the store's own format.
async function appendMany(events: Array<{ at: string; kind: string; note: string; data: Record<string, unknown> }>): Promise<void> {
  let doc: { version: number; events: unknown[] };
  let raw: string | null = null;
  try {
    raw = await gezel.fs.read(FEEDBACK);
  } catch {
    raw = null;
  }
  if (raw === null) doc = { version: 1, events: [] };
  else {
    doc = JSON.parse(raw);
    if (doc.version !== 1 || !Array.isArray(doc.events)) throw new Error(FEEDBACK + ' is not a version 1 log; it was left untouched.');
  }
  doc.events.push(...events);
  await gezel.fs.write(FEEDBACK, JSON.stringify(doc, null, 2) + '\n');
}

let note = '';
const today = localDay(Date.now());

if (input.action === 'log') {
  const text = (input.text ?? '').trim();
  if (!text) throw new Error("log needs 'text' (the customer's words).");
  const day = input.receivedAt ? normalizeDate(input.receivedAt) : today;
  if (!day) throw new Error("receivedAt must be a date, e.g. '2026-11-02'.");
  const source = sourceOf(input.source ?? 'other');
  const rating = ratingOf(input.rating ?? input.stars, 5);
  const events = await feedback.list();
  const list = entries(events);
  const existing = list.find((e) => textKey(e.text, e.author) === textKey(text, input.author));
  const tagged = input.themes?.trim()
    ? await ensureThemes(input.themes, THEME_KINDS.includes(String(input.kind)) ? String(input.kind) : guessKind([{ rating, text }]))
    : { ids: [], created: [] };
  if (existing) {
    await feedback.append({
      kind: 'edited',
      note: 'Logged again.',
      data: {
        feedbackId: existing.id,
        ...(rating !== null ? { rating } : {}),
        ...(input.source ? { source } : {}),
        ...(typeof input.replyNeeded === 'boolean' ? { replyNeeded: input.replyNeeded } : {}),
        ...(tagged.ids.length ? { themes: tagged.ids } : {}),
      },
    });
    note = 'Already in the log as ' + existing.id + '; updated it.';
  } else {
    const id = 'fb-' + nextFeedbackNumber(events);
    const owed = needsReply(source, rating, input.replyNeeded);
    await feedback.append({
      kind: feedbackKind(source),
      note: text,
      data: {
        id,
        source,
        ...(rating !== null ? { rating } : {}),
        ...(input.author?.trim() ? { author: input.author.trim() } : {}),
        day,
        themes: tagged.ids,
        replyNeeded: owed,
      },
    });
    note =
      'Logged ' + id + (tagged.ids.length ? ' under ' + (await themeNames(tagged.ids)) : ', not sorted into a theme yet') +
      (tagged.created.length ? ' (new theme: ' + tagged.created.join(', ') + ')' : '') + (owed ? '; it needs a reply' : '') + '.';
  }
} else if (input.action === 'tag') {
  if (!input.themes?.trim()) throw new Error("tag needs 'themes' (names, comma-separated).");
  const list = entries(await feedback.list());
  const ids = feedbackIds(list);
  const chosen = list.filter((e) => ids.includes(e.id));
  const tagged = await ensureThemes(input.themes, THEME_KINDS.includes(String(input.kind)) ? String(input.kind) : guessKind(chosen));
  for (const id of ids) {
    await feedback.append({ kind: 'tagged', note: 'Sorted into themes.', data: { feedbackId: id, themes: tagged.ids } });
  }
  note =
    'Sorted ' + ids.join(', ') + ' under ' + (await themeNames(tagged.ids)) +
    (tagged.created.length ? ' (new theme: ' + tagged.created.join(', ') + ')' : '') + '.';
} else if (input.action === 'reply') {
  const list = entries(await feedback.list());
  const [id] = feedbackIds(list);
  const text = (input.reply ?? '').trim();
  if (!text && input.posted !== true) throw new Error("reply needs 'reply' (the text to post).");
  if (text) {
    await feedback.append({ kind: 'reply', note: text, data: { feedbackId: id, posted: input.posted === true } });
  } else {
    await feedback.append({ kind: 'replied', note: 'Reply posted.', data: { feedbackId: id } });
  }
  note = input.posted === true ? 'Marked ' + id + ' replied.' : 'Saved a reply to ' + id + '; it is not posted yet.';
} else if (input.action === 'mark_replied') {
  const list = entries(await feedback.list());
  const [id] = feedbackIds(list);
  await feedback.append({ kind: 'replied', note: input.note ?? 'Reply posted.', data: { feedbackId: id } });
  note = 'Marked ' + id + ' replied.';
} else if (input.action === 'add_action') {
  const title = (input.title ?? '').trim();
  if (!title) throw new Error("add_action needs 'title'.");
  const dueAt = input.dueAt ? normalizeDate(input.dueAt) : null;
  if (input.dueAt && !dueAt) throw new Error("dueAt must be a date, e.g. '2026-12-01'.");
  const theme = input.theme?.trim() ? (await ensureThemes(input.theme, 'problem')).ids[0] : undefined;
  const fields: Record<string, unknown> = {
    ...(theme ? { theme } : {}),
    ...(input.owner?.trim() ? { owner: input.owner.trim() } : {}),
    ...(dueAt ? { dueAt } : {}),
    ...(input.note?.trim() ? { notes: input.note.trim() } : {}),
  };
  const existing = (await actions.list()).find((a) => nameKey(a.fields.title) === nameKey(title));
  if (existing) {
    await actions.update(existing.id, { fields });
    note = 'Updated the action ' + String(existing.fields.title) + '.';
  } else {
    const record = await actions.add({ status: 'todo', fields: { title, ...fields } });
    note = 'Added ' + record.id + ': ' + title + '.';
  }
} else if (input.action === 'set_action') {
  const status = String(input.status ?? '').trim().toLowerCase();
  if (!ACTION_STAGES.includes(status)) throw new Error("set_action needs status 'todo', 'doing' or 'done'.");
  const id = await resolveAction();
  const record = (await actions.get(id))!;
  await actions.transition(id, status, input.note ? { note: input.note } : {});
  if (status === 'done') await actions.update(id, { fields: { doneAt: today } });
  note = String(record.fields.title) + ' (' + id + ') is ' + (status === 'todo' ? 'to do' : status === 'doing' ? 'under way' : 'done') + '.';
} else if (input.action === 'import') {
  const file = String(input.file ?? '').trim().replace(/\\/g, '/').replace(/^\.?\/+/, '');
  if (!file) throw new Error("import needs 'file', e.g. 'imports/reviews.csv'.");
  if (!/\.(csv|tsv|txt)$/i.test(file) || file.split('/').includes('..')) {
    throw new Error('import reads a .csv, .tsv or .txt file in the workspace, e.g. imports/reviews.csv.');
  }
  let text: string;
  try {
    text = await gezel.fs.read(file);
  } catch {
    throw new Error("Could not read '" + file + "'. Add the file on the Customer Voice page first; it lands under imports/.");
  }
  const parsed = csvFeedback(text, sourceOf(input.source ?? file));
  if (parsed.columns.text === undefined) throw new Error('No column of customer comments found in ' + file + '. Name one review, comment, feedback or text.');
  const events = await feedback.list();
  const seen = new Set(entries(events).map((e) => textKey(e.text, e.author)));
  let next = nextFeedbackNumber(events);
  let repeats = 0;
  const rows = parsed.items.slice(0, 2000);
  const fresh: Array<{ at: string; kind: string; note: string; data: Record<string, unknown> }> = [];
  for (const item of rows) {
    const key = textKey(item.text, item.author);
    if (seen.has(key)) {
      repeats += 1;
      continue;
    }
    seen.add(key);
    fresh.push({
      at: new Date().toISOString(),
      kind: feedbackKind(item.source),
      note: item.text,
      data: {
        id: 'fb-' + next++,
        source: item.source,
        ...(item.rating !== null ? { rating: item.rating } : {}),
        ...(item.author ? { author: item.author } : {}),
        day: item.day ?? today,
        themes: [],
        replyNeeded: needsReply(item.source, item.rating, undefined),
        imported: file,
      },
    });
  }
  if (fresh.length) await appendMany(fresh);
  note =
    'Imported ' + fresh.length + (fresh.length === 1 ? ' entry' : ' entries') + ' from ' + file +
    (repeats ? ' (' + repeats + ' already in the log)' : '') + (parsed.blank ? ', skipped ' + parsed.blank + (parsed.blank === 1 ? ' blank row' : ' blank rows') : '') +
    (parsed.items.length > rows.length ? ', stopped at 2000 rows' : '') +
    (fresh.length ? '; ' + fresh.length + ' new ' + (fresh.length === 1 ? 'entry is' : 'entries are') + ' not sorted into themes yet' : '') + '.';
} else if (input.action !== 'status' && input.action !== 'list') {
  throw new Error("Unknown action '" + input.action + "'. Use status, log, tag, reply, mark_replied, add_action, set_action, import, or list.");
}

const list = entries(await feedback.list());
const themeRecords = await themes.list();
const actionRecords = await actions.list();
const view = picture(themeRecords, list, actionRecords, Date.now());

let listing = '';
if (input.action === 'list') {
  const names: Record<string, string> = {};
  themeRecords.forEach((t) => { names[t.id] = String(t.fields.name); });
  const themeId = input.theme ? themeRecords.find((t) => t.id === input.theme!.trim().toLowerCase() || nameKey(t.fields.name) === nameKey(input.theme))?.id : undefined;
  if (input.theme && !themeId) throw new Error("No theme '" + input.theme + "'. Themes: " + themeRecords.map((t) => t.id + ' ' + String(t.fields.name)).join(', ') + '.');
  const shown = themeId ? list.filter((e) => e.themes.includes(themeId)) : list;
  listing =
    shown.map((e) => feedbackLine(e, names) + (e.reply ? '; reply: "' + quote(e.reply, 160) + '"' : '')).join('\n') || 'No feedback logged yet.';
  if (!themeId && actionRecords.length) {
    listing += '\nActions: ' + actionRecords.map((a) => '[' + a.status + '] ' + String(a.fields.title) + ' (' + a.id + ')').join(' | ');
  }
}

gezel.output({
  themes: view.themes,
  repliesNeeded: view.repliesNeeded,
  unsorted: view.unsorted,
  openActions: view.openActions,
  summary: input.action === 'list' ? listing : (note ? note + ' ' : '') + view.summary,
});

